catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    // OnLoad par newValue '1' fix hai: saved values mat udao, sirf drop_address state set karo
    if (isLoading) {
        if (newValue == '1') {
            g_form.setMandatory('drop_address', false);
            g_form.setReadOnly('drop_address', true);
        }
        return;
    }

    if (newValue == '1') {
        // Admission , patient ko mandatory hatayo
        g_form.setMandatory('related_admission', false);
        g_form.setMandatory('requested_for', false);

        // contact_name, contact_phone, hospital ko wapas editable karo
        g_form.setReadOnly('contact_name', false);
        g_form.setReadOnly('contact_phone', false);
        g_form.setReadOnly('hospital', false);

        // drop_address ko read-only aur non-mandatory karo; pickup_address khali karo
        g_form.setMandatory('drop_address', false);
        g_form.setReadOnly('drop_address', true);
        g_form.setValue('pickup_address', '');

        // Switch hone par purani values clear karo
        g_form.setValue('related_admission', '');
        g_form.setValue('requested_for', '');
        g_form.setValue('hospital', '');
        g_form.setValue('contact_name', '');
        g_form.setValue('contact_phone', '');
        g_form.setValue('drop_address', '');

    } else if (newValue == '2' || newValue == '3') {
        // related_admission mandatory karo
        g_form.setMandatory('related_admission', true);

        // Patient, contact_name, contact_phone, hospital ko read-only karo
        g_form.setMandatory('requested_for', false);
        g_form.setReadOnly('requested_for', true);

        g_form.setMandatory('contact_name', false);
        g_form.setReadOnly('contact_name', true);

        g_form.setMandatory('contact_phone', false);
        g_form.setReadOnly('contact_phone', true);

        g_form.setMandatory('hospital', false);
        g_form.setReadOnly('hospital', true);

        // drop_address editable karo
        g_form.setReadOnly('drop_address', false);


        if (oldValue && oldValue != '2' && oldValue != '3') {
			g_form.setValue('related_admission','');
			g_form.setValue('requested_for','');
            g_form.setValue('hospital', '');
            g_form.setValue('contact_phone', '');
            g_form.setValue('contact_name', '');
            g_form.setValue('drop_address', '');
        }

        // Hospital se pickup_address populate karo
        var hos = g_form.getValue('hospital');
        if (hos) {
            g_form.getReference('hospital', function(hosRec) {
                if (hosRec && hosRec.name) {
                    g_form.setValue('pickup_address', hosRec.name);
                } else {
                    g_form.setValue('pickup_address', '');
                }
            });
        } else {
            g_form.setValue('pickup_address', '');
        }

    } else {
        // Baaki kisi value ya empty hone par normal state reset karo
        g_form.setMandatory('related_admission', false);
        g_form.setReadOnly('requested_for', false);
        g_form.setReadOnly('contact_name', false);
        g_form.setReadOnly('contact_phone', false);
        g_form.setReadOnly('hospital', false);
        g_form.setReadOnly('drop_address', false);

        g_form.setValue('pickup_address', '');
        g_form.setValue('drop_address', '');
    }
}
